/**
 * @file ndviLayer.js
 * @description Manages rendering and opacity of dynamic XYZ raster tile overlays
 * generated by Google Earth Engine for Sentinel-2 NDVI visualization over MapLibre GL JS.
 */

export class NdviLayerManager {
  /**
   * @param {Object} map - Active MapLibre map instance
   */
  constructor(map) {
    this.map = map;
    this.sourceId = "ndvi-source";
    this.layerId = "ndvi-layer";
    this.defaultOpacity = 0.75;
  }

  /**
   * Mounts a new dynamic XYZ raster tile layer onto the map underneath administrative vector labels.
   * @param {string} tileUrlTemplate - Dynamic XYZ URL template (e.g. from Earth Engine)
   * @param {number} [opacity=0.75] - Layer opacity between 0.0 and 1.0
   */
  setNdviLayer(tileUrlTemplate, opacity = this.defaultOpacity) {
    this.removeCurrentLayer();

    if (!tileUrlTemplate || !this.map) return;

    try {
      this.map.addSource(this.sourceId, {
        type: "raster",
        tiles: [tileUrlTemplate],
        tileSize: 256,
        attribution: "Sentinel-2 &copy; ESA / Google Earth Engine"
      });

      // Insert under political borders and labels so country/state/city names remain readable
      const beforeLayerId = this.map.getLayer("boundary-country") ? "boundary-country" : undefined;

      this.map.addLayer(
        {
          id: this.layerId,
          type: "raster",
          source: this.sourceId,
          paint: {
            "raster-opacity": opacity
          }
        },
        beforeLayerId
      );
    } catch (err) {
      console.error("Failed to mount NDVI raster layer:", err);
    }
  }

  /**
   * Updates opacity of the currently mounted raster layer.
   * @param {number} opacity - Opacity value between 0.0 and 1.0
   */
  setOpacity(opacity) {
    if (this.map && this.map.getLayer(this.layerId)) {
      this.map.setPaintProperty(this.layerId, "raster-opacity", opacity);
    }
  }

  /**
   * Removes active NDVI tile layer from map.
   */
  removeCurrentLayer() {
    if (!this.map) return;
    try {
      if (this.map.getLayer(this.layerId)) {
        this.map.removeLayer(this.layerId);
      }
      if (this.map.getSource(this.sourceId)) {
        this.map.removeSource(this.sourceId);
      }
    } catch (err) {
      console.warn("Error removing NDVI layer:", err);
    }
  }
}
